head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
scwin.vScrenID = "ULDSTF20800.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_NEWPREFSTK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.newprefstk.condition" + "&{P}param01=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
            "&{P}param02=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
            "&{P}param03=" + $c.stf.getObjectValue(txb_ISU_CD) + "&{P}param04=" + $c.stf.getObjectValue(txb_ISU_CD);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_NEWPREFSTK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.newprefstkdtl.condition" + "&{P}param01=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
            "&{P}param02=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + // 상장구분
            "&{P}param03=" + $c.stf.getObjectValue(txb_ISU_CD) + "&{P}param04=" + $c.stf.getObjectValue(txb_ISU_CD);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.img_ISU_NM_onclick = function() {
    $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, js_market, "A");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var Rows;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        Rows = dts_List_1.getTotalRow();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        Rows = dts_List_2.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.txb_ISU_CD_onblur = function() {
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "신형우선주 종목현황", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "신형우선주 주식발행현황", "", "8");
    }
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    MaxTab_01.setSelectedTabIndex(1);
    scwin.fn_list_sync();
};
